package com.coach.domain.fsrs

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.double
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlin.math.abs
import kotlin.math.max
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Replays review logs generated by the official py-fsrs 5.1.3 implementation and requires
 * the Kotlin kernel to produce the same difficulty, stability and interval at every step.
 *
 * The fixture is committed (`src/jvmTest/resources/fsrs5-golden.json`) so the test runs
 * offline; regenerate it with `tools/fsrs-golden/gen_fsrs5_golden.py` (pinned dependency).
 */
class Fsrs5ReferenceParityTest {
    private val fixture = Json.parseToJsonElement(
        checkNotNull(javaClass.getResourceAsStream("/fsrs5-golden.json")) {
            "fsrs5-golden.json is missing from the test resources"
        }.bufferedReader().use { it.readText() }
    ).jsonObject

    private fun Double.closeTo(expected: Double) =
        abs(this - expected) <= 1e-9 * max(1.0, abs(expected))

    @Test
    fun defaultWeightsAreTheOfficialParameterSet() {
        val expected = fixture["scheduler"]!!.jsonObject["parameters"]!!.jsonArray.map { it.jsonPrimitive.double }
        assertEquals(expected.size, DEFAULT_FSRS5_WEIGHTS.size)
        for (i in expected.indices) {
            assertTrue(
                DEFAULT_FSRS5_WEIGHTS[i].closeTo(expected[i]),
                "weight $i: official ${expected[i]} vs kernel ${DEFAULT_FSRS5_WEIGHTS[i]}",
            )
        }
    }

    @Test
    fun everyStepMatchesTheOfficialScheduler() {
        val sequences = fixture["sequences"]!!.jsonArray
        assertTrue(sequences.size >= 5, "fixture must cover fresh, lapse, same-day, overdue and max-interval paths")
        var comparedSteps = 0
        for (sequence in sequences) {
            val name = sequence.jsonObject["name"]!!.jsonPrimitive.content
            var card = Fsrs5.newCard(dueDay = 0)
            for (step in sequence.jsonObject["steps"]!!.jsonArray) {
                val obj = step.jsonObject
                val day = obj["day"]!!.jsonPrimitive.int.toLong()
                val rating = FsrsRating.of(obj["rating"]!!.jsonPrimitive.int)
                card = Fsrs5.review(card, rating, day)
                val expectedStability = obj["stability"]!!.jsonPrimitive.double
                val expectedDifficulty = obj["difficulty"]!!.jsonPrimitive.double
                val expectedInterval = obj["intervalDays"]!!.jsonPrimitive.int
                val where = "$name day=$day rating=$rating"
                assertNotNull(card.stability)
                assertTrue(
                    card.stability.closeTo(expectedStability),
                    "$where stability ${card.stability} != official $expectedStability",
                )
                assertNotNull(card.difficulty)
                assertTrue(
                    card.difficulty.closeTo(expectedDifficulty),
                    "$where difficulty ${card.difficulty} != official $expectedDifficulty",
                )
                assertEquals(
                    expectedInterval,
                    (card.dueDay - day).toInt(),
                    "$where interval ${card.dueDay - day} != official $expectedInterval",
                )
                comparedSteps++
            }
        }
        assertTrue(comparedSteps >= 40, "compared $comparedSteps review steps against the official log")
    }

    @Test
    fun theSameRecordAlwaysGivesTheSameSchedule() {
        val ratings = listOf(
            FsrsRating.GOOD, FsrsRating.GOOD, FsrsRating.AGAIN, FsrsRating.HARD, FsrsRating.EASY,
        )
        val days = listOf(0L, 3L, 30L, 31L, 90L)
        fun play(): FsrsState {
            var card = Fsrs5.newCard(0)
            for (i in ratings.indices) card = Fsrs5.review(card, ratings[i], days[i])
            return card
        }
        assertEquals(play(), play())
    }
}
